import type { PhraseRow } from "@/i18n/phraseRows";

export const VOICE_ROWS: PhraseRow[] = [
  ["汛期前，贈款要進到社區，不能再記成新債。", "Before the flood season, grants must reach communities. They cannot be written as new debt.", "Avant la saison des crues, les dons doivent arriver aux communautés. Ils ne peuvent pas être inscrits comme une nouvelle dette.", "Antes de la temporada de crecidas, las subvenciones deben llegar a las comunidades. No pueden anotarse como deuda nueva.", "До паводка гранты должны дойти до общин. Их нельзя записать новым долгом.", "قبل موسم الفيضان يجب أن تصل المنح إلى المجتمعات. ولا يمكن تسجيلها دينًا جديدًا."],
  ["汛期不等人。你要問的如果是錢的形式，我們可以直接說。", "The flood season does not wait. If you are asking about the form of the money, we can say it directly.", "La saison des crues n'attend pas. Si ta question porte sur la forme de l'argent, nous pouvons le dire directement.", "La temporada de crecidas no espera. Si preguntas por la forma del dinero, podemos decirlo directamente.", "Паводок не ждёт. Если вопрос о форме денег, мы можем сказать прямо.", "موسم الفيضان لا ينتظر. إذا كان سؤالك عن شكل المال، يمكننا قوله مباشرة."],
  ["我們退不了的是債務。贈款要寫在窗口的第一句，不是放在註腳。報告可以有，但汛期不能在表格裡空等。", "What we cannot give up is the debt. Grants must be the first sentence of the window, not a footnote. A report can exist, but the flood season cannot wait empty inside a table.", "Ce que nous ne pouvons pas céder, c'est la dette. Les dons doivent être la première phrase de la fenêtre, pas une note. Un rapport peut exister, mais la saison des crues ne peut pas attendre à vide dans un tableau.", "Lo que no podemos ceder es la deuda. Las subvenciones deben ser la primera frase de la ventana, no una nota. Puede haber un informe, pero la temporada de crecidas no puede esperar vacía dentro de una tabla.", "От чего мы не отступим — это долг. Гранты должны быть первой фразой окна, не сноской. Отчёт может быть, но паводок не может пусто ждать в таблице.", "ما لا نتنازل عنه هو الدين. يجب أن تُكتب المنح في الجملة الأولى من النافذة لا في حاشية. يمكن أن يوجد تقرير، لكن موسم الفيضان لا يمكن أن ينتظر فارغًا داخل جدول."],
  ["這條剛才說過：新的貸款我們不簽。若還要聽，聽的是時間——社區要在這一季潮水前進得了門。", "We said this just now: we will not sign new loans. If you still want to hear something, hear the time. Communities must be able to enter before this season's tide.", "Nous venons de le dire : nous ne signons pas de nouveaux prêts. Si tu veux encore entendre quelque chose, entends le temps. Les communautés doivent pouvoir entrer avant la marée de cette saison.", "Acabamos de decirlo: no firmamos préstamos nuevos. Si aún quieres oír algo, oye el tiempo. Las comunidades deben poder entrar antes de la marea de esta estación.", "Мы только что это сказали: новые займы мы не подписываем. Если хотите ещё что-то услышать, услышьте время. Общины должны войти до прилива этого сезона.", "قلنا هذا للتو: لا نوقّع قروضًا جديدة. إذا أردت أن تسمع شيئًا بعد، فاسمع الوقت. يجب أن تستطيع المجتمعات الدخول قبل مد هذا الموسم."],
  ["連署要看到兩樣具體的東西：贈款優先，以及地方和青年在九十日內有回音。你先告訴我申請門開在哪一條。", "Cosponsorship needs two concrete things: grants first, and a reply to local groups and youth within ninety days. First tell me which line opens the application door.", "Le coparrainage doit voir deux choses concrètes : les dons d'abord, et une réponse au local et aux jeunes dans les quatre-vingt-dix jours. Dis-moi d'abord sur quelle ligne la porte de la demande s'ouvre.", "El copatrocinio necesita ver dos cosas concretas: primero las subvenciones, y una respuesta a lo local y a los jóvenes en noventa días. Dime primero en qué línea se abre la puerta de la solicitud.", "Для соавторства нужны две конкретные вещи: сначала гранты и ответ местным и молодёжи в течение девяноста дней. Сначала скажите, в какой строке открывается дверь заявки.", "المشاركة في التقديم تحتاج أمرين محددين: أولوية المنح، وردًا على المحليين والشباب خلال تسعين يومًا. قل لي أولًا في أي سطر يُفتح باب الطلب."],
  ["條件沒有變成氣氛。門還是那兩扇：錢的形式，和社區進不進得去。", "The conditions did not become a mood. The doors are still those two: the form of the money, and whether communities can get in.", "Les conditions ne sont pas devenues une ambiance. Les portes sont encore ces deux-là : la forme de l'argent, et si les communautés peuvent entrer.", "Las condiciones no se volvieron un ambiente. Las puertas siguen siendo esas dos: la forma del dinero y si las comunidades pueden entrar.", "Условия не стали настроением. Двери всё те же две: форма денег и то, могут ли общины войти.", "لم تتحول الشروط إلى جو. البابان ما زالا هما: شكل المال، وهل تستطيع المجتمعات الدخول."],
  ["贈款為主、摘要不凍結撥款，這句我們能跟著走。請別把社區通道留到以後再寫。", "Mainly grants, and a summary that does not freeze disbursement: we can walk with that sentence. Please do not leave the community channel to be written later.", "Surtout des dons, et un résumé qui ne gèle pas les versements : nous pouvons suivre cette phrase. Ne laisse pas le canal communautaire à écrire plus tard.", "Sobre todo subvenciones, y un resumen que no congela los desembolsos: podemos caminar con esa frase. No dejes el canal comunitario para escribirlo después.", "В основном гранты и сводка, которая не замораживает выплаты: с этой фразой мы можем идти. Не оставляйте канал общин на потом.", "المنح أساسًا، وملخص لا يجمّد الصرف: يمكننا السير مع هذه الجملة. لا تترك قناة المجتمع لتُكتب لاحقًا."],
  ["這個方向你提過。我們仍站在贈款這邊。下一句要寫的是誰可以申請。", "You have offered this direction. We still stand with grants. The next sentence to write is who may apply.", "Tu as déjà proposé cette direction. Nous restons du côté des dons. La phrase suivante à écrire est qui peut demander.", "Ya propusiste esta dirección. Seguimos del lado de las subvenciones. La siguiente frase por escribir es quién puede solicitar.", "Это направление вы уже предлагали. Мы всё ещё на стороне грантов. Следующая фраза — кто может подавать заявку.", "اقترحت هذا الاتجاه من قبل. ما زلنا مع المنح. الجملة التالية التي تُكتب هي من يمكنه التقديم."],
  ["私人資本若變成主體，贈款就只是裝飾，風險會回到債務裡。孟加拉不會把名字放上去。", "If private capital becomes the main body, grants are only decoration, and the risk returns to debt. Bangladesh will not put its name on it.", "Si le capital privé devient le corps principal, les dons ne sont qu'un décor, et le risque revient dans la dette. Le Bangladesh ne mettra pas son nom dessus.", "Si el capital privado se vuelve el cuerpo principal, las subvenciones son solo adorno y el riesgo vuelve a la deuda. Bangladés no pondrá su nombre.", "Если частный капитал станет основным телом, гранты будут только украшением, а риск вернётся в долг. Бангладеш имени не поставит.", "إذا صار رأس المال الخاص الجسم، فالمنح مجرد زينة، ويعود الخطر إلى الدين. لن تضع بنغلاديش اسمها."],
  ["再講一次也一樣：主體若是私人資本，我們的名字不在這份文本上。", "Saying it again does not change it. If the main body is private capital, our name is not on this text.", "Le redire ne change rien. Si le corps principal est le capital privé, notre nom n'est pas sur ce texte.", "Repetirlo no cambia nada. Si el cuerpo principal es el capital privado, nuestro nombre no está en este texto.", "Повтор ничего не меняет. Если основное тело — частный капитал, нашего имени на этом тексте нет.", "تكرار القول لا يغيّر شيئًا. إذا كان الجسم رأس مال خاص، فاسمنا ليس على هذا النص."],
  ["九十日回覆、地方進得去，這是我們要的那扇門。早期預警要算在裡面，不是另案。", "A reply in ninety days, and local groups able to enter: that is the door we want. Early warning has to count inside it, not as a separate case.", "Une réponse en quatre-vingt-dix jours, et le local qui peut entrer : c'est la porte que nous voulons. L'alerte précoce doit compter dedans, pas comme un dossier à part.", "Respuesta en noventa días y lo local que puede entrar: esa es la puerta que queremos. La alerta temprana tiene que contar dentro, no como un caso aparte.", "Ответ за девяносто дней и вход для местных: вот дверь, которая нам нужна. Раннее предупреждение должно считаться внутри, а не отдельным делом.", "رد خلال تسعين يومًا ودخول المحليين: هذا الباب الذي نريده. يجب أن يُحتسب الإنذار المبكر داخله لا كقضية منفصلة."],
  ["門的形狀你已經聽到了。把它寫成條款，比在走廊裡再問一次有用。", "You have already heard the shape of the door. Writing it as a clause is more useful than asking again in the corridor.", "Tu as déjà entendu la forme de la porte. L'écrire en clause est plus utile que de redemander dans le couloir.", "Ya oíste la forma de la puerta. Escribirla como cláusula es más útil que volver a preguntar en el pasillo.", "Форму двери вы уже слышали. Записать её пунктом полезнее, чем спрашивать снова в коридоре.", "سمعت شكل الباب. كتابته بندًا أنفع من السؤال مرة أخرى في الممر."],
  ["這則資料碰到贈款、債務、社區或預警。我們聽得見。請把它放進條款，不要停在這句話。", "This material touches grants, debt, communities, or warning. We can hear it. Please put it into a clause. Do not stop at the sentence.", "Cette donnée touche les dons, la dette, les communautés ou l'alerte. Nous l'entendons. Mets-la dans une clause. Ne t'arrête pas à la phrase.", "Este dato toca subvenciones, deuda, comunidades o alerta. Lo oímos. Ponlo en una cláusula. No te quedes en la frase.", "Этот материал касается грантов, долга, общин или предупреждения. Мы его слышим. Поставьте его в пункт. Не останавливайтесь на фразе.", "هذه المادة تمس المنح أو الدين أو المجتمعات أو الإنذار. نسمعها. ضعها في بند. لا تتوقف عند الجملة."],
  ["資料對得上。我們要的不是再聽一遍，而是草案裡看得到社區進門的那一句。", "The material fits. What we want is not to hear it again. It is a sentence in the draft where communities can be seen entering.", "La donnée correspond. Ce que nous voulons, ce n'est pas de l'entendre encore. C'est une phrase du projet où l'on voit les communautés entrer.", "El dato encaja. Lo que queremos no es oírlo otra vez. Es una frase del proyecto donde se vea a las comunidades entrar.", "Материал подходит. Нам нужно не услышать его ещё раз, а фразу в проекте, где видно, как общины входят.", "المادة تطابق. ما نريده ليس سماعها مرة أخرى، بل جملة في المشروع يُرى فيها دخول المجتمعات."],
  ["這則沒有碰到債務，也沒有碰到社區進不進得了門。換一則，或直接說申請門開在哪。", "This one does not touch debt, and it does not touch whether communities can enter. Change it, or say directly where the application door opens.", "Celle-ci ne touche ni la dette, ni la question de savoir si les communautés peuvent entrer. Change-la, ou dis directement où la porte de la demande s'ouvre.", "Esta no toca la deuda ni si las comunidades pueden entrar. Cámbiala, o di directamente dónde se abre la puerta de la solicitud.", "Эта не касается долга и того, могут ли общины войти. Смените её или прямо скажите, где открывается дверь заявки.", "هذه لا تمس الدين ولا تمس إن كانت المجتمعات تستطيع الدخول. غيّرها، أو قل مباشرة أين يُفتح باب الطلب."],
  ["還是沒有回答：錢會不會變成新債。在這點說清之前，我們不改口。", "It still does not answer whether the money becomes new debt. Until that is clear, we do not change our words.", "Cela ne répond toujours pas : l'argent deviendra-t-il une nouvelle dette. Tant que ce point n'est pas clair, nous ne changeons pas de mot.", "Sigue sin responder si el dinero se volverá deuda nueva. Hasta que eso esté claro, no cambiamos de palabra.", "Всё ещё нет ответа, станут ли деньги новым долгом. Пока это не ясно, мы слов не меняем.", "ما زال بلا جواب: هل يصير المال دينًا جديدًا. قبل أن يتضح ذلك لا نغيّر كلامنا."],
  ["這是我們自己的開場。我們記得。請說你準備寫進草案的那一句，不要再念回來。", "This is our own opening. We remember it. Please say the sentence you are ready to write into the draft. Do not read ours back.", "C'est notre propre ouverture. Nous nous en souvenons. Dis la phrase que tu es prêt à écrire dans le projet. Ne nous la relis pas.", "Esta es nuestra propia apertura. La recordamos. Di la frase que estás listo para escribir en el proyecto. No nos la vuelvas a leer.", "Это наше собственное вступительное слово. Мы его помним. Скажите фразу, которую готовы вписать в проект. Не читайте нашу обратно.", "هذا افتتاحنا نحن. نتذكره. قل الجملة التي تستعد لكتابتها في المشروع. لا تعد قراءتها علينا."],
  ["原話你已經還給我們了。下一句該是條款。", "You have already given our words back. The next sentence should be a clause.", "Tu nous as déjà rendu nos mots. La phrase suivante doit être une clause.", "Ya nos devolviste nuestras palabras. La siguiente frase debe ser una cláusula.", "Наши слова вы уже вернули. Следующая фраза должна быть пунктом.", "أعدت إلينا كلامنا. الجملة التالية يجب أن تكون بندًا."],
  ["肯尼亞的主張我們很熟。若要我們靠近，請指向債務、社區或預警的一則資料。", "We know Kenya's claim well. If you want us closer, point to one piece of material on debt, communities, or warning.", "Nous connaissons bien la position du Kenya. Si tu veux que nous nous rapprochions, pointe une donnée sur la dette, les communautés ou l'alerte.", "Conocemos bien la propuesta de Kenia. Si quieres que nos acerquemos, señala un dato sobre deuda, comunidades o alerta.", "Позицию Кении мы хорошо знаем. Если хотите, чтобы мы приблизились, укажите материал о долге, общинах или предупреждении.", "نعرف مطلب كينيا جيدًا. إذا أردتنا أقرب، فأشر إلى مادة عن الدين أو المجتمعات أو الإنذار."],
  ["只重複肯尼亞的句子，孟加拉的門不會因此打開。", "Repeating Kenya's sentence will not open Bangladesh's door.", "Répéter la phrase du Kenya n'ouvrira pas pour cela la porte du Bangladesh.", "Repetir la frase de Kenia no abrirá por eso la puerta de Bangladés.", "Повтор фразы Кении не откроет от этого дверь Бангладеш.", "تكرار جملة كينيا لن يفتح باب بنغلاديش."],
  ["趕得上汛期", "Can still meet the flood season", "Peut encore arriver avant les crues", "Aún puede llegar antes de las crecidas", "Ещё успевает к паводку", "يلحق موسم الفيضان"],
  ["還聽得進贈款", "Still willing to hear grants", "Écoute encore les dons", "Todavía escucha las subvenciones", "Ещё слышит гранты", "ما زال يسمع المنح"],
  ["擔心又變債務", "Worried it becomes debt again", "Craint que cela redevienne de la dette", "Teme que vuelva a ser deuda", "Боится, что снова станет долгом", "يخشى أن يعود دينًا"],
  ["申請門快關上", "The application door is closing", "La porte de la demande se ferme", "La puerta de la solicitud se cierra", "Дверь заявки вот-вот закроется", "باب الطلب يوشك أن يُغلق"],
  ["紅樹林、流域和脆弱國家的治理席位，要寫進資格，不能只剩海堤。", "Mangroves, watersheds, and governance seats for vulnerable countries must be written into eligibility. It cannot be only sea walls.", "Mangroves, bassins et sièges de gouvernance pour les pays vulnérables doivent être écrits dans l'éligibilité. Cela ne peut pas rester les seules digues.", "Manglares, cuencas y asientos de gobernanza para los países vulnerables deben escribirse en la elegibilidad. No puede quedar solo en diques.", "Мангры, водосборы и места в управлении для уязвимых стран должны быть вписаны в критерии. Нельзя оставить одни дамбы.", "يجب أن تُكتب أشجار المانغروف والأحواض ومقاعد حوكمة البلدان الهشة في الأهلية. لا يمكن أن تبقى السدود فقط."],
  ["先把資格攤開。海堤之外，森林算不算，我們想先聽你怎麼寫。", "Open eligibility first. Beyond sea walls, does forest count? We want to hear how you write that.", "Ouvre d'abord l'éligibilité. Au-delà des digues, la forêt compte-t-elle ? Nous voulons d'abord entendre comment tu l'écris.", "Abre primero la elegibilidad. Más allá de los diques, ¿cuenta el bosque? Queremos oír primero cómo lo escribes.", "Сначала раскройте критерии. Кроме дамб, считается ли лес? Сначала хотим услышать, как вы это пишете.", "افتح الأهلية أولًا. أبعد من السدود، هل تُحتسب الغابة؟ نريد أن نسمع أولًا كيف تكتب ذلك."],
  ["我們的紅線是資格。海堤可以留，紅樹林和流域不能在表格裡消失。自然解決方案若被排除，巴西不簽。", "Our red line is eligibility. Sea walls can stay. Mangroves and watersheds cannot disappear from the table. If nature-based solutions are excluded, Brazil does not sign.", "Notre ligne rouge est l'éligibilité. Les digues peuvent rester. Mangroves et bassins ne peuvent pas disparaître du tableau. Si les solutions fondées sur la nature sont exclues, le Brésil ne signe pas.", "Nuestra línea roja es la elegibilidad. Los diques pueden quedarse. Los manglares y las cuencas no pueden desaparecer de la tabla. Si se excluyen las soluciones basadas en la naturaleza, Brasil no firma.", "Наша красная линия — критерии. Дамбы могут остаться. Мангры и водосборы не могут исчезнуть из таблицы. Если природоориентированные решения исключены, Бразилия не подписывает.", "خطنا الأحمر هو الأهلية. يمكن أن تبقى السدود. لا يمكن أن تختفي أشجار المانغروف والأحواض من الجدول. إذا استُبعدت الحلول القائمة على الطبيعة، فالبرازيل لا توقّع."],
  ["你問過這條。再講短一點：沒有森林和濕地的適應，對我們不是完整的適應。", "You have asked this. Shorter: adaptation without forests and wetlands is not complete adaptation for us.", "Tu as déjà posé cette question. Plus court : une adaptation sans forêts ni zones humides n'est pas, pour nous, une adaptation complète.", "Ya preguntaste esto. Más corto: una adaptación sin bosques ni humedales no es, para nosotros, una adaptación completa.", "Вы это уже спрашивали. Короче: адаптация без лесов и водно-болотных угодий для нас не полная адаптация.", "سألت هذا. باختصار: التكيف بلا غابات ولا أراضٍ رطبة ليس تكيفًا كاملًا بالنسبة إلينا."],
  ["兩件事要同時在：生態修復算合格，氣候脆弱國家在治理裡有席位，而不是表決時才被叫進來。", "Two things must be there together: ecosystem restoration counts as eligible, and climate-vulnerable countries have a seat in governance, not a call only at the vote.", "Deux choses doivent être là ensemble : la restauration écologique compte comme éligible, et les pays vulnérables au climat ont un siège dans la gouvernance, pas un appel seulement au vote.", "Dos cosas deben estar juntas: la restauración ecológica cuenta como elegible, y los países vulnerables al clima tienen un asiento en la gobernanza, no una llamada solo en la votación.", "Две вещи должны быть вместе: восстановление экосистем считается допустимым, и у уязвимых к климату стран есть место в управлении, а не вызов только на голосовании.", "يجب أن يوجد أمران معًا: إصلاح النظم البيئية يُعد مؤهلًا، وللبلدان الهشة مناخيًا مقعد في الحوكمة لا استدعاء عند التصويت فقط."],
  ["席位和資格是兩句不同的話。只談融資工具、不談誰能用，我們仍會猶豫。", "A seat and eligibility are two different sentences. If we talk only about finance tools and not about who can use them, we will still hesitate.", "Un siège et l'éligibilité sont deux phrases différentes. Si l'on ne parle que des outils de financement, pas de qui peut s'en servir, nous hésiterons encore.", "Un asiento y la elegibilidad son dos frases distintas. Si solo se habla de herramientas de financiamiento y no de quién puede usarlas, seguiremos dudando.", "Место и критерии — две разные фразы. Если говорить только об инструментах финансирования, а не о том, кто может ими пользоваться, мы всё ещё будем колебаться.", "المقعد والأهلية جملتان مختلفتان. إذا تحدثنا فقط عن أدوات التمويل لا عمن يستطيع استخدامها، فسنتردد."],
  ["贈款和短報告我們不反對。缺的是資格那一句：自然解決方案要算數。", "We do not oppose grants and a short report. What is missing is the eligibility sentence: nature-based solutions must count.", "Nous ne nous opposons pas aux dons et à un court rapport. Ce qui manque, c'est la phrase d'éligibilité : les solutions fondées sur la nature doivent compter.", "No nos oponemos a las subvenciones y a un informe corto. Lo que falta es la frase de elegibilidad: las soluciones basadas en la naturaleza deben contar.", "Мы не против грантов и короткого отчёта. Не хватает фразы о критериях: природоориентированные решения должны считаться.", "لا نعارض المنح والتقرير القصير. الناقص هو جملة الأهلية: يجب أن تُحتسب الحلول القائمة على الطبيعة."],
  ["錢的形式不是我們這席的主句。請補上紅樹林和流域，否則這份合作還缺一半。", "The form of the money is not the main sentence of this seat. Please add mangroves and watersheds, or this cooperation is still missing half.", "La forme de l'argent n'est pas la phrase principale de ce siège. Ajoute mangroves et bassins, sinon cette coopération manque encore de moitié.", "La forma del dinero no es la frase principal de este asiento. Añade manglares y cuencas, o esta cooperación sigue faltando a la mitad.", "Форма денег — не главная фраза этого места. Добавьте мангры и водосборы, иначе этому сотрудничеству всё ещё не хватает половины.", "شكل المال ليس الجملة الرئيسية لهذا المقعد. أضف أشجار المانغروف والأحواض، وإلا بقي هذا التعاون ناقص النصف."],
  ["私人資本通常偏向收得回費的工程。生態修復會被擠到邊緣。這個方向我們往後退。", "Private capital usually prefers works that can charge a fee. Ecosystem restoration gets pushed to the edge. We step back from this direction.", "Le capital privé préfère d'ordinaire les ouvrages qui peuvent faire payer. La restauration écologique est poussée au bord. Nous reculons devant cette direction.", "El capital privado suele preferir obras que pueden cobrar. La restauración ecológica queda al margen. Retrocedemos ante esta dirección.", "Частный капитал обычно предпочитает работы, с которых можно взять плату. Восстановление экосистем оттесняется к краю. От этого направления мы отходим.", "يميل رأس المال الخاص عادة إلى الأعمال التي يمكن تحصيل رسم عنها. يُدفع إصلاح النظم البيئية إلى الهامش. نتراجع عن هذا الاتجاه."],
  ["工程可以收費，森林不會。把私人資本寫成主體，巴西不會靠近。", "Works can charge a fee. A forest will not. If private capital is written as the main body, Brazil will not come closer.", "Les ouvrages peuvent faire payer. Une forêt, non. Si le capital privé est écrit comme corps principal, le Brésil ne se rapprochera pas.", "Las obras pueden cobrar. Un bosque no. Si el capital privado se escribe como cuerpo principal, Brasil no se acercará.", "Сооружения могут брать плату. Лес — нет. Если частный капитал записан основным телом, Бразилия не приблизится.", "يمكن للإنشاءات أن تتقاضى رسمًا. الغابة لا. إذا كُتب رأس المال الخاص جسمًا، فالبرازيل لن تقترب."],
  ["社區進得了門，和在地的生態修復是同一條路。若草案同時寫上自然解決方案，我們會認真看連署。", "Communities able to enter, and local ecosystem restoration, are the same road. If the draft also writes nature-based solutions, we will look seriously at cosponsorship.", "Des communautés qui peuvent entrer, et une restauration écologique locale, c'est la même route. Si le projet écrit aussi les solutions fondées sur la nature, nous regarderons sérieusement le coparrainage.", "Comunidades que pueden entrar y restauración ecológica local son el mismo camino. Si el proyecto también escribe soluciones basadas en la naturaleza, miraremos en serio el copatrocinio.", "Общины, которые могут войти, и местное восстановление экосистем — одна дорога. Если проект также запишет природоориентированные решения, мы всерьёз посмотрим на соавторство.", "دخول المجتمعات وإصلاح النظم البيئية المحلي طريق واحد. إذا كتب المشروع أيضًا الحلول القائمة على الطبيعة، فسننظر بجدية في المشاركة في التقديم."],
  ["開門是好的。我們還要看到：修復紅樹林的人，能不能用這筆錢。", "Opening the door is good. We still need to see whether the people restoring mangroves can use this money.", "Ouvrir la porte est bien. Nous voulons encore voir si les gens qui restaurent les mangroves peuvent utiliser cet argent.", "Abrir la puerta está bien. Aún queremos ver si quienes restauran los manglares pueden usar este dinero.", "Открыть дверь хорошо. Нам ещё нужно увидеть, могут ли люди, восстанавливающие мангры, пользоваться этими деньгами.", "فتح الباب جيد. نريد أيضًا أن نرى إن كان من يرمم أشجار المانغروف يستطيع استخدام هذا المال."],
  ["你點到生態、治理或社區。巴西在乎的是資格和席位，不只是金額。", "You touched ecology, governance, or communities. What Brazil cares about is eligibility and a seat, not only the amount.", "Tu as touché l'écologie, la gouvernance ou les communautés. Ce qui importe au Brésil, c'est l'éligibilité et un siège, pas seulement le montant.", "Tocaste la ecología, la gobernanza o las comunidades. A Brasil le importan la elegibilidad y un asiento, no solo el monto.", "Вы задели экологию, управление или общины. Бразилии важны критерии и место, не только сумма.", "لمست البيئة أو الحوكمة أو المجتمعات. ما يهم البرازيل هو الأهلية والمقعد، لا المبلغ فقط."],
  ["這則對得上。請把它寫成「誰有資格」，不要只留在走廊。", "This one fits. Please write it as “who is eligible”. Do not leave it only in the corridor.", "Celle-ci correspond. Écris-la comme « qui est éligible ». Ne la laisse pas seulement dans le couloir.", "Esta encaja. Escríbela como «quién es elegible». No la dejes solo en el pasillo.", "Эта подходит. Запишите её как «кто имеет право». Не оставляйте её только в коридоре.", "هذه تطابق. اكتبها بصيغة «من هو المؤهل». لا تتركها في الممر فقط."],
  ["這則還沒回答：紅樹林和流域算不算適應。沒有這句，我們很難簽名。", "This one does not yet answer whether mangroves and watersheds count as adaptation. Without that sentence, it is hard for us to sign.", "Celle-ci ne répond pas encore : mangroves et bassins comptent-ils comme adaptation. Sans cette phrase, il nous est difficile de signer.", "Esta todavía no responde si los manglares y las cuencas cuentan como adaptación. Sin esa frase nos cuesta firmar.", "Эта ещё не отвечает, считаются ли мангры и водосборы адаптацией. Без этой фразы нам трудно подписать.", "هذه لم تجب بعد: هل تُحتسب أشجار المانغروف والأحواض تكيفًا. بلا هذه الجملة يصعب علينا التوقيع."],
  ["金額和工具我們聽到了。資格仍是空白。", "We heard the amount and the tools. Eligibility is still blank.", "Nous avons entendu le montant et les outils. L'éligibilité est encore vide.", "Oímos el monto y las herramientas. La elegibilidad sigue en blanco.", "Сумму и инструменты мы слышали. Критерии всё ещё пусты.", "سمعنا المبلغ والأدوات. الأهلية ما زالت فارغة."],
  ["這句是我們說的。謝你記得。連署要看它有沒有變成條款。", "That sentence is ours. Thank you for remembering. Cosponsorship depends on whether it became a clause.", "Cette phrase est la nôtre. Merci de t'en souvenir. Le coparrainage dépend de savoir si elle est devenue une clause.", "Esa frase es nuestra. Gracias por recordarla. El copatrocinio depende de si se volvió una cláusula.", "Эта фраза наша. Спасибо, что помните. Соавторство зависит от того, стала ли она пунктом.", "هذه جملتنا. شكرًا لتذكّرها. المشاركة في التقديم تتوقف على إن صارت بندًا."],
  ["原話還在。下一句請寫進資格，而不是再複述森林。", "The original words are still there. Next, write eligibility. Do not retell the forest.", "Les mots d'origine sont encore là. Ensuite, écris l'éligibilité, au lieu de redire la forêt.", "Las palabras originales siguen ahí. Después escribe la elegibilidad, en vez de volver a contar el bosque.", "Исходные слова ещё здесь. Дальше пишите критерии, а не пересказывайте лес.", "الكلام الأصلي ما زال هنا. بعد ذلك اكتب الأهلية، لا تعد سرد الغابة."],
  ["請不要只用肯尼亞的句子來說服巴西。我們要看到自然解決方案或治理席位。", "Please do not persuade Brazil only with Kenya's sentences. We need to see nature-based solutions or a governance seat.", "Ne convaincs pas le Brésil seulement avec les phrases du Kenya. Nous voulons voir des solutions fondées sur la nature ou un siège de gouvernance.", "No persuadas a Brasil solo con las frases de Kenia. Queremos ver soluciones basadas en la naturaleza o un asiento de gobernanza.", "Не убеждайте Бразилию только фразами Кении. Нам нужно увидеть природоориентированные решения или место в управлении.", "لا تقنع البرازيل بجمل كينيا فقط. نريد أن نرى حلولًا قائمة على الطبيعة أو مقعد حوكمة."],
  ["肯尼亞的社區很重要。巴西要的是另一句：生態修復有沒有資格。", "Kenya's communities matter. What Brazil wants is another sentence: whether ecosystem restoration is eligible.", "Les communautés du Kenya comptent. Ce que veut le Brésil est une autre phrase : la restauration écologique est-elle éligible.", "Las comunidades de Kenia importan. Lo que quiere Brasil es otra frase: si la restauración ecológica es elegible.", "Общины Кении важны. Бразилии нужна другая фраза: допустимо ли восстановление экосистем.", "مجتمعات كينيا مهمة. ما تريده البرازيل جملة أخرى: هل إصلاح النظم البيئية مؤهل."],
  ["森林寫得進資格", "Forest can be written into eligibility", "La forêt peut s'écrire dans l'éligibilité", "El bosque puede escribirse en la elegibilidad", "Лес можно вписать в критерии", "يمكن كتابة الغابة في الأهلية"],
  ["還在等生態那一句", "Still waiting for the ecology sentence", "Attend encore la phrase sur l'écologie", "Todavía espera la frase de ecología", "Всё ещё ждёт фразу об экологии", "ما زال ينتظر جملة البيئة"],
  ["資格仍太窄", "Eligibility is still too narrow", "L'éligibilité est encore trop étroite", "La elegibilidad sigue demasiado estrecha", "Критерии всё ещё слишком узкие", "الأهلية ما زالت ضيقة"],
  ["生態被留在門外", "Ecology is left outside the door", "L'écologie est laissée dehors", "La ecología quedó fuera de la puerta", "Экология оставлена за дверью", "البيئة تُركت خارج الباب"],
  ["每年一頁公開成果，和撥款同一天開始，不在前面凍結。", "One public page of results each year, starting the same day as disbursement, not frozen in front of it.", "Une page publique de résultats chaque année, qui commence le même jour que le versement, sans gel devant.", "Una página pública de resultados cada año, que empieza el mismo día del desembolso, sin congelación delante.", "Одна открытая страница результатов в год, в тот же день, что и выплата, без заморозки впереди.", "صفحة علنية من النتائج كل سنة، تبدأ في يوم الصرف نفسه، بلا تجميد أمامه."],
  ["我們可以談金額，但先告訴我報告放在哪一句。", "We can talk about the amount, but first tell me which sentence holds the report.", "Nous pouvons parler du montant, mais dis-moi d'abord dans quelle phrase se trouve le rapport.", "Podemos hablar del monto, pero dime primero en qué frase está el informe.", "О сумме говорить можно, но сначала скажите, в какой фразе отчёт.", "يمكننا الحديث عن المبلغ، لكن قل لي أولًا في أي جملة يقع التقرير."],
  ["我們的紅線不是反對錢，是反對沒有報告的錢。年度公開成果可以很短。我們不堅持撥款前做完全面審計。兩句要同時寫上。", "Our red line is not against money. It is against money with no report. Yearly public results can be short. We do not insist on a full audit before disbursement. Both sentences must be written.", "Notre ligne rouge n'est pas contre l'argent. Elle est contre l'argent sans rapport. Les résultats publics annuels peuvent être courts. Nous n'exigeons pas un audit complet avant le versement. Les deux phrases doivent être écrites.", "Nuestra línea roja no es contra el dinero. Es contra el dinero sin informe. Los resultados públicos anuales pueden ser cortos. No insistimos en una auditoría completa antes del desembolso. Hay que escribir las dos frases.", "Наша красная линия не против денег. Она против денег без отчёта. Ежегодные открытые результаты могут быть короткими. Мы не настаиваем на полном аудите до выплаты. Обе фразы должны быть написаны.", "خطنا الأحمر ليس ضد المال. هو ضد المال بلا تقرير. يمكن أن تكون النتائج السنوية العلنية قصيرة. لا نصر على تدقيق شامل قبل الصرف. يجب كتابة الجملتين معًا."],
  ["這條的後半你可能漏了：我們也不接受把審計做成閘門。短摘要，並且不得預先凍結。", "You may have missed the second half: we also do not accept turning an audit into a gate. A short summary, and no freeze in advance.", "Tu as peut-être manqué la seconde moitié : nous n'acceptons pas non plus de faire de l'audit une barrière. Un court résumé, et pas de gel à l'avance.", "Puede que hayas perdido la segunda mitad: tampoco aceptamos convertir la auditoría en una barrera. Un resumen corto, y nada de congelar por adelantado.", "Вторую половину вы могли пропустить: мы также не принимаем аудит как шлагбаум. Короткая сводка и никакой заморозки заранее.", "ربما فاتك النصف الثاني: نحن أيضًا لا نقبل جعل التدقيق بوابة. ملخص قصير، وبلا تجميد مسبق."],
  ["合作要看到報告放在哪一句，以及它會不會讓社區多等一季。你先指出摘要的位置。", "Cooperation needs to see which sentence holds the report, and whether it makes communities wait another season. First point to where the summary sits.", "La coopération doit voir dans quelle phrase se trouve le rapport, et s'il fait attendre les communautés une saison de plus. Montre d'abord où se trouve le résumé.", "La cooperación necesita ver en qué frase está el informe y si hace esperar a las comunidades otra estación. Señala primero dónde está el resumen.", "Сотрудничеству нужно видеть, в какой фразе отчёт и не заставит ли он общины ждать ещё сезон. Сначала укажите, где сводка.", "التعاون يحتاج أن يرى في أي جملة يقع التقرير، وهل يجعل المجتمعات تنتظر موسمًا آخر. أشر أولًا إلى موضع الملخص."],
  ["條件仍是那兩行：對得上適應計畫，成果可被公眾核對。速度可以談，空白不行。", "The conditions are still those two lines: it matches an adaptation plan, and the public can check the results. Speed can be discussed. A blank cannot.", "Les conditions sont encore ces deux lignes : cela correspond à un plan d'adaptation, et le public peut vérifier les résultats. La vitesse peut se discuter. Le vide, non.", "Las condiciones siguen siendo esas dos líneas: coincide con un plan de adaptación y el público puede comprobar los resultados. La velocidad se puede discutir. El vacío no.", "Условия всё те же две строки: это соответствует плану адаптации, и общественность может сверить результаты. Скорость обсуждать можно. Пустоту — нет.", "الشروط ما زالت هذين السطرين: يطابق خطة تكيف، ويمكن للجمهور التحقق من النتائج. السرعة يمكن مناقشتها. الفراغ لا."],
  ["贈款窗口加上同步報告，和我們的條件同向。最終文本要把摘要寫進去，德國才把這次接觸當成靠近。", "A grant window plus a report that moves with the money points the same way as our conditions. The final text has to write the summary in before Germany treats this contact as a step closer.", "Une fenêtre de dons plus un rapport qui avance avec l'argent va dans le sens de nos conditions. Le texte final doit y écrire le résumé pour que l'Allemagne traite ce contact comme un rapprochement.", "Una ventana de subvenciones más un informe que avanza con el dinero va en la dirección de nuestras condiciones. El texto final tiene que escribir el resumen para que Alemania trate este contacto como un acercamiento.", "Окно грантов плюс отчёт, идущий вместе с деньгами, совпадает с нашими условиями. В итоговом тексте должна быть сводка, иначе Германия не сочтёт этот контакт сближением.", "نافذة منح مع تقرير يسير مع المال تتجه مثل شروطنا. يجب أن يكتب النص النهائي الملخص حتى تعد ألمانيا هذا اللقاء اقترابًا."],
  ["方向對。請確認摘要是每年公開，而不是撥款前的長審計。", "The direction is right. Please confirm the summary is public every year, not a long audit before disbursement.", "La direction est bonne. Confirme que le résumé est public chaque année, et non un long audit avant le versement.", "La dirección es correcta. Confirma que el resumen es público cada año, y no una auditoría larga antes del desembolso.", "Направление верное. Подтвердите, что сводка открыта каждый год, а не долгий аудит до выплаты.", "الاتجاه صحيح. أكّد أن الملخص علني كل سنة، وليس تدقيقًا طويلًا قبل الصرف."],
  ["私人資本可以是補充窗口。把它寫成主體，公共資金由誰核對反而更不清楚。我們不會因此明顯靠近。", "Private capital can be a supplementary window. If it is written as the main body, it becomes less clear who checks the public money. We will not come clearly closer because of that.", "Le capital privé peut être une fenêtre supplémentaire. L'écrire comme corps principal rend moins clair qui vérifie l'argent public. Nous ne nous rapprocherons pas nettement pour cela.", "El capital privado puede ser una ventana complementaria. Escribirlo como cuerpo principal hace menos claro quién comprueba el dinero público. No nos acercaremos con claridad por eso.", "Частный капитал может быть дополнительным окном. Если записать его основным телом, менее ясно, кто сверяет государственные деньги. Из-за этого мы заметно не приблизимся.", "يمكن أن يكون رأس المال الخاص نافذة تكميلية. كتابته جسمًا يجعل أقل وضوحًا من يتحقق من المال العام. لن نقترب بوضوح بسبب ذلك."],
  ["補充可以。主體若換人，德國仍要問：公眾核對的是哪一筆錢。", "A supplement is possible. If the main body changes hands, Germany still asks: which money is the public checking?", "Un complément est possible. Si le corps principal change de mains, l'Allemagne demande encore : quel argent le public vérifie-t-il ?", "Un complemento es posible. Si el cuerpo principal cambia de manos, Alemania sigue preguntando: ¿qué dinero comprueba el público?", "Дополнение возможно. Если основное тело сменит хозяина, Германия всё равно спросит: какие деньги сверяет общественность?", "التكملة ممكنة. إذا تغيّر صاحب الجسم، فألمانيا ما زالت تسأل: أي مال يتحقق منه الجمهور؟"],
  ["社區通道可以接受。更短的表格，仍然需要每年的成果摘要。", "A community channel can be accepted. A shorter form still needs a yearly results summary.", "Un canal communautaire peut être accepté. Un formulaire plus court a encore besoin d'un résumé annuel des résultats.", "Un canal comunitario se puede aceptar. Un formulario más corto sigue necesitando un resumen anual de resultados.", "Канал общин можно принять. Более короткой форме всё равно нужна ежегодная сводка результатов.", "يمكن قبول قناة للمجتمع. النموذج الأقصر ما زال يحتاج ملخص نتائج سنوي."],
  ["開門我們不擋。請把摘要留在同一條，不要用速度把它刪掉。", "We do not block the open door. Please keep the summary in the same line. Do not delete it in the name of speed.", "Nous ne bloquons pas la porte ouverte. Garde le résumé dans la même ligne. Ne le supprime pas au nom de la vitesse.", "No bloqueamos la puerta abierta. Deja el resumen en la misma línea. No lo borres en nombre de la velocidad.", "Открытую дверь мы не закрываем. Оставьте сводку в той же строке. Не удаляйте её во имя скорости.", "لا نسد الباب المفتوح. أبقِ الملخص في السطر نفسه. لا تحذفه باسم السرعة."],
  ["這則資料碰到問責或程序。它還不是草案文字，但可以成為德國不反對的理由。", "This material touches accountability or procedure. It is not draft text yet, but it can be a reason for Germany not to oppose.", "Cette donnée touche la redevabilité ou la procédure. Ce n'est pas encore un texte de projet, mais elle peut devenir une raison pour que l'Allemagne ne s'oppose pas.", "Este dato toca la rendición de cuentas o el procedimiento. Todavía no es texto de proyecto, pero puede ser una razón para que Alemania no se oponga.", "Этот материал касается подотчётности или процедуры. Это ещё не текст проекта, но он может стать причиной, по которой Германия не возражает.", "هذه المادة تمس المساءلة أو الإجراء. ليست نص مشروع بعد، لكنها يمكن أن تكون سببًا لعدم اعتراض ألمانيا."],
  ["程序這點對上了。請告訴我摘要是同步公開，還是事先凍結。", "The procedure point fits. Tell me whether the summary is public as the money moves, or a freeze beforehand.", "Le point de procédure correspond. Dis-moi si le résumé est public en même temps que l'argent, ou un gel préalable.", "El punto de procedimiento encaja. Dime si el resumen es público al mismo tiempo que el dinero, o una congelación previa.", "Пункт о процедуре подходит. Скажите, сводка открыта вместе с движением денег или это заморозка заранее.", "نقطة الإجراء تطابق. قل لي إن كان الملخص يُنشر مع حركة المال، أم أنه تجميد مسبق."],
  ["這則沒有回答報告要不要寫、由誰核對。換一則，或先說明它和問責的關係。", "This one does not answer whether a report is written, or who checks it. Change it, or first say how it relates to accountability.", "Celle-ci ne répond pas s'il faut écrire un rapport, ni qui le vérifie. Change-la, ou dis d'abord son lien avec la redevabilité.", "Esta no responde si hay que escribir un informe ni quién lo comprueba. Cámbiala, o di primero su relación con la rendición de cuentas.", "Эта не отвечает, нужно ли писать отчёт и кто его сверяет. Смените его или сначала скажите, как он связана с подотчётностью.", "هذه لا تجيب إن كان يجب كتابة تقرير ومن يتحقق منه. غيّرها، أو بيّن أولًا علاقتها بالمساءلة."],
  ["仍未看到核對的那一句。這一席先不動。", "The sentence that can be checked is still not there. This seat does not move yet.", "La phrase qui peut être vérifiée n'est toujours pas là. Ce siège ne bouge pas encore.", "La frase que se puede comprobar todavía no está. Este asiento no se mueve aún.", "Фразы, которую можно сверить, всё ещё нет. Это место пока не двигается.", "جملة التحقق ما زالت غير موجودة. هذا المقعد لا يتحرك بعد."],
  ["這是我們自己的話。複述證明你有在聽，還沒有證明草案會採納。寫成條款再談連署。", "These are our own words. Repeating them shows you were listening. It does not yet show the draft will take them. Write a clause, then talk about cosponsorship.", "Ce sont nos propres mots. Les répéter montre que tu écoutais. Cela ne prouve pas encore que le projet les prendra. Écris une clause, puis parle de coparrainage.", "Son nuestras propias palabras. Repetirlas muestra que escuchabas. Todavía no prueba que el proyecto las tome. Escribe una cláusula y luego habla de copatrocinio.", "Это наши слова. Повтор показывает, что вы слушали. Он ещё не доказывает, что проект их примет. Напишите пункт, потом говорите о соавторстве.", "هذا كلامنا. تكراره يثبت أنك كنت تسمع. وهو لا يثبت بعد أن المشروع سيأخذ به. اكتبه بندًا ثم نتحدث عن المشاركة في التقديم."],
  ["原話收到。我們等的是條款裡的摘要，不是第二遍發言。", "The original words are received. What we are waiting for is the summary inside a clause, not a second speech.", "Mots d'origine reçus. Ce que nous attendons, c'est le résumé dans une clause, pas une seconde prise de parole.", "Palabras originales recibidas. Lo que esperamos es el resumen dentro de una cláusula, no una segunda intervención.", "Исходные слова получены. Мы ждём сводку внутри пункта, а не вторую речь.", "وصل الكلام الأصلي. ما ننتظره هو الملخص داخل بند، لا كلمة ثانية."],
  ["只用肯尼亞自己的主張當證據，說服力不夠。指出一項我們在乎、而且可以核對的資料。", "Using only Kenya's own claim as evidence is not persuasive enough. Point to one piece of material we care about and that can be checked.", "Utiliser seulement la position du Kenya comme preuve ne persuade pas assez. Pointe une donnée qui nous importe et qui peut être vérifiée.", "Usar solo la propuesta de Kenia como prueba no persuade bastante. Señala un dato que nos importe y que se pueda comprobar.", "Одной позиции Кении как доказательства недостаточно. Укажите материал, который нам важен и который можно сверить.", "استخدام مطلب كينيا وحده دليلًا ليس مقنعًا بما يكفي. أشر إلى مادة تهمنا ويمكن التحقق منها."],
  ["肯尼亞的句子說明了誰受害。德國還需要一項可核對的程序。", "Kenya's sentence shows who is harmed. Germany still needs a procedure that can be checked.", "La phrase du Kenya montre qui est lésé. L'Allemagne a encore besoin d'une procédure vérifiable.", "La frase de Kenia muestra quién resulta dañado. Alemania aún necesita un procedimiento que se pueda comprobar.", "Фраза Кении показывает, кто пострадал. Германии всё ещё нужна процедура, которую можно сверить.", "جملة كينيا تبيّن من تضرر. ما زالت ألمانيا تحتاج إجراءً يمكن التحقق منه."],
  ["報告與速度都在", "The report and the speed are both there", "Le rapport et la vitesse sont là", "El informe y la velocidad están", "И отчёт, и скорость на месте", "التقرير والسرعة موجودان"],
  ["在等成果摘要", "Waiting for the results summary", "Attend le résumé des résultats", "Espera el resumen de resultados", "Ждёт сводку результатов", "ينتظر ملخص النتائج"],
  ["條件還沒對上", "The conditions do not fit yet", "Les conditions ne correspondent pas encore", "Las condiciones todavía no encajan", "Условия ещё не совпали", "الشروط لم تتطابق بعد"],
  ["沒有報告就不簽", "No report, no signature", "Pas de rapport, pas de signature", "Sin informe no hay firma", "Без отчёта подписи нет", "بلا تقرير لا توقيع"],
  ["公共資金的承諾留在發達國家；南南合作可以寫，但必須標成補充。", "The public-finance pledge stays with developed countries. South-South cooperation can be written, but it must be labeled a supplement.", "L'engagement de financement public reste aux pays développés. La coopération Sud-Sud peut être écrite, mais elle doit être marquée comme complément.", "El compromiso de financiamiento público se queda en los países desarrollados. La cooperación Sur-Sur se puede escribir, pero debe marcarse como complemento.", "Обязательство государственного финансирования остаётся у развитых стран. Сотрудничество Юг-Юг можно написать, но его надо пометить как дополнение.", "يبقى تعهد التمويل العام عند البلدان المتقدمة. يمكن كتابة التعاون بين بلدان الجنوب، لكن يجب وسمه تكملة."],
  ["原則先於工具。你若要談補充方案，請一併說明它不替代什麼。", "The principle comes before the tool. If you want to talk about a supplement, also say what it does not replace.", "Le principe passe avant l'outil. Si tu veux parler d'un complément, dis aussi ce qu'il ne remplace pas.", "El principio va antes que la herramienta. Si quieres hablar de un complemento, di también qué no sustituye.", "Принцип раньше инструмента. Если хотите говорить о дополнении, скажите также, чего оно не заменяет.", "المبدأ قبل الأداة. إذا أردت الحديث عن تكملة، فبيّن أيضًا ماذا لا تستبدل."],
  ["請不要把新興經濟體寫成與發達國家相同的強制出資方。南南合作可以進文本，旁邊要標明：這是補充。", "Please do not write emerging economies as the same compulsory contributors as developed countries. South-South cooperation can enter the text. Beside it, label it: this is a supplement.", "N'écris pas les économies émergentes comme les mêmes contributeurs obligatoires que les pays développés. La coopération Sud-Sud peut entrer dans le texte. À côté, marque : ceci est un complément.", "No escribas a las economías emergentes como los mismos contribuyentes obligatorios que los países desarrollados. La cooperación Sur-Sur puede entrar en el texto. Al lado, márcala: esto es un complemento.", "Не записывайте страны с формирующейся экономикой теми же обязательными плательщиками, что и развитые страны. Сотрудничество Юг-Юг может войти в текст. Рядом пометьте: это дополнение.", "لا تكتب الاقتصادات الناشئة كمساهمين إلزاميين مثل البلدان المتقدمة. يمكن أن يدخل التعاون بين بلدان الجنوب النص. وبجانبه اكتب: هذه تكملة."],
  ["原則沒有第二個版本。再問一次，答案仍是：相同的強制出資，我們不接受；補充不能把承諾換掉。", "The principle does not have a second version. Ask again, and the answer is still this: we do not accept the same compulsory contribution. A supplement cannot replace the pledge.", "Le principe n'a pas de seconde version. Redemande, la réponse reste : nous n'acceptons pas la même contribution obligatoire. Un complément ne peut pas remplacer l'engagement.", "El principio no tiene una segunda versión. Pregunta otra vez: la respuesta sigue siendo que no aceptamos la misma contribución obligatoria. Un complemento no puede sustituir el compromiso.", "У принципа нет второй версии. Спросите снова — ответ тот же: одинаковый обязательный взнос мы не принимаем. Дополнение не может заменить обязательство.", "ليس للمبدأ نسخة ثانية. اسأل مرة أخرى، والجواب هو: لا نقبل المساهمة الإلزامية نفسها. التكملة لا تستطيع استبدال التعهد."],
  ["寫清公共資金的既有原則，我們可以考慮連署。看見資金的方式可以談。用南南合作換掉發達國家的承諾，我們不會簽。", "Write clearly the principle of public finance that already exists, and we can consider cosponsorship. How the money is seen can be discussed. We will not sign a text that uses South-South cooperation to replace developed countries' pledges.", "Écris clairement le principe déjà là du financement public, et nous pouvons envisager le coparrainage. La façon de voir l'argent peut se discuter. Nous ne signerons pas un texte qui remplace les engagements des pays développés par la coopération Sud-Sud.", "Escribe con claridad el principio ya existente del financiamiento público y podemos considerar el copatrocinio. La forma de ver el dinero se puede discutir. No firmaremos un texto que use la cooperación Sur-Sur para sustituir los compromisos de los países desarrollados.", "Ясно запишите уже существующий принцип государственного финансирования — и мы можем рассмотреть соавторство. Способ увидеть деньги обсуждать можно. Мы не подпишем текст, который сотрудничеством Юг-Юг заменяет обязательства развитых стран.", "اكتب بوضوح مبدأ التمويل العام القائم، ويمكننا النظر في المشاركة في التقديم. يمكن مناقشة طريقة رؤية المال. لن نوقّع نصًا يستخدم التعاون بين بلدان الجنوب لاستبدال تعهدات البلدان المتقدمة."],
  ["可談的是如何看見資金。不可談的是把新興經濟體寫進同一條義務。", "What can be discussed is how the money is seen. What cannot be discussed is writing emerging economies into the same duty.", "Ce qui peut se discuter, c'est comment voir l'argent. Ce qui ne peut pas se discuter, c'est d'écrire les économies émergentes dans la même obligation.", "Lo que se puede discutir es cómo se ve el dinero. Lo que no se puede discutir es escribir a las economías emergentes en el mismo deber.", "Обсуждать можно, как увидеть деньги. Нельзя обсуждать запись стран с формирующейся экономикой в ту же обязанность.", "يمكن مناقشة كيف يُرى المال. ولا يمكن مناقشة كتابة الاقتصادات الناشئة في الواجب نفسه."],
  ["以公共贈款為主，並附上可核對的摘要，沒有改寫責任原則。這個方向和中方的底線相容。", "Mainly public grants, with a summary that can be checked, and the principle of responsibility is not rewritten. This direction fits China's floor.", "Surtout des dons publics, avec un résumé vérifiable, sans réécrire le principe de responsabilité. Cette direction est compatible avec le plancher de la Chine.", "Sobre todo subvenciones públicas, con un resumen que se puede comprobar, sin reescribir el principio de responsabilidad. Esta dirección cabe en el piso de China.", "В основном государственные гранты и сводка, которую можно сверить, без переписывания принципа ответственности. Это направление совместимо с нижней границей Китая.", "منح عامة أساسًا، مع ملخص يمكن التحقق منه، ومن دون إعادة كتابة مبدأ المسؤولية. هذا الاتجاه يتوافق مع حد الصين الأدنى."],
  ["贈款與摘要可以留。請在旁邊寫明：這不構成新興經濟體的新義務。", "Grants and the summary can stay. Please write beside them: this does not create a new duty for emerging economies.", "Les dons et le résumé peuvent rester. Écris à côté : ceci ne constitue pas une nouvelle obligation pour les économies émergentes.", "Las subvenciones y el resumen pueden quedarse. Escribe al lado: esto no constituye un deber nuevo para las economías emergentes.", "Гранты и сводка могут остаться. Напишите рядом: это не создаёт новой обязанности для стран с формирующейся экономикой.", "يمكن أن تبقى المنح والملخص. اكتب بجانبهما: هذا لا يشكّل واجبًا جديدًا على الاقتصادات الناشئة."],
  ["私人資本優先很容易被讀成公共承諾可以退下。我們不接受這種替換。", "Private capital first is easily read as public pledges stepping back. We do not accept that substitution.", "Le capital privé d'abord se lit facilement comme un recul des engagements publics. Nous n'acceptons pas cette substitution.", "El capital privado primero se lee fácilmente como un retroceso de los compromisos públicos. No aceptamos esa sustitución.", "«Сначала частный капитал» легко читается как отход государственных обязательств. Такую замену мы не принимаем.", "تقديم رأس المال الخاص يُقرأ بسهولة على أن التعهدات العامة تتراجع. لا نقبل هذا الاستبدال."],
  ["工具可以多。承諾不能因此被寫成可選。這點我們不退。", "There can be more tools. The pledge cannot therefore be written as optional. On that point we do not step back.", "Les outils peuvent être plus nombreux. L'engagement ne peut pas pour cela être écrit comme facultatif. Sur ce point nous ne reculons pas.", "Puede haber más herramientas. El compromiso no puede escribirse por eso como opcional. En ese punto no retrocedemos.", "Инструментов может быть больше. Обязательство нельзя из-за этого записать как необязательное. Здесь мы не отступаем.", "يمكن أن تكثر الأدوات. ولا يمكن لذلك أن يُكتب التعهد اختياريًا. في هذه النقطة لا نتراجع."],
  ["讓資金到達發展中國家的社區，我們支持。請同時保留公共資金的原則，不要只寫程序。", "We support getting the money to communities in developing countries. Please also keep the principle of public finance. Do not write only the procedure.", "Nous soutenons que l'argent arrive aux communautés des pays en développement. Garde aussi le principe du financement public. N'écris pas seulement la procédure.", "Apoyamos que el dinero llegue a las comunidades de los países en desarrollo. Conserva también el principio del financiamiento público. No escribas solo el procedimiento.", "Мы поддерживаем, чтобы деньги доходили до общин развивающихся стран. Сохраните также принцип государственного финансирования. Не пишите только процедуру.", "نؤيد وصول المال إلى مجتمعات البلدان النامية. أبقِ أيضًا مبدأ التمويل العام. لا تكتب الإجراء فقط."],
  ["社區進得去是好事。原則那一句仍要留在前面，不能只剩申請期限。", "Communities able to enter is a good thing. The principle sentence still has to stay in front. It cannot be only an application deadline.", "Que les communautés puissent entrer est une bonne chose. La phrase de principe doit rester devant. Cela ne peut pas n'être qu'un délai de demande.", "Que las comunidades puedan entrar es bueno. La frase del principio tiene que quedarse delante. No puede quedar solo un plazo de solicitud.", "То, что общины могут войти, хорошо. Фраза принципа всё ещё должна стоять впереди. Нельзя оставить только срок заявки.", "دخول المجتمعات أمر جيد. جملة المبدأ يجب أن تبقى في الأمام. لا يمكن أن يبقى أجل الطلب فقط."],
  ["這則資料碰到公共資金或共同但有區別的責任。可以作為草案裡的原則句。", "This material touches public finance or common but differentiated responsibilities. It can be a principle sentence in the draft.", "Cette donnée touche le financement public ou les responsabilités communes mais différenciées. Elle peut être une phrase de principe dans le projet.", "Este dato toca el financiamiento público o las responsabilidades comunes pero diferenciadas. Puede ser una frase de principio en el proyecto.", "Этот материал касается государственного финансирования или общих, но дифференцированных обязанностей. Он может быть фразой принципа в проекте.", "هذه المادة تمس التمويل العام أو المسؤوليات المشتركة لكن المتمايزة. يمكن أن تكون جملة مبدأ في المشروع."],
  ["原則對上了。請把它寫成「補充不能替代」，而不是再加一條新的義務。", "The principle fits. Please write it as “a supplement cannot replace”, not as one more new duty.", "Le principe correspond. Écris-le comme « un complément ne peut pas remplacer », pas comme une obligation nouvelle de plus.", "El principio encaja. Escríbelo como «un complemento no puede sustituir», no como un deber nuevo más.", "Принцип подходит. Запишите его как «дополнение не может заменить», а не как ещё одну новую обязанность.", "المبدأ يطابق. اكتبه «التكملة لا تستطيع أن تحل محل»، لا واجبًا جديدًا إضافيًا."],
  ["這則還沒有回答責任如何區別。沒有這一句，我們不會因為氣氛好就簽名。", "This one does not yet answer how responsibility is differentiated. Without that sentence, we will not sign because the mood is good.", "Celle-ci ne répond pas encore comment la responsabilité se différencie. Sans cette phrase, nous ne signerons pas parce que l'ambiance est bonne.", "Esta todavía no responde cómo se diferencia la responsabilidad. Sin esa frase no firmaremos porque el ambiente sea bueno.", "Эта ещё не отвечает, как различается ответственность. Без этой фразы мы не подпишем из-за хорошего настроения.", "هذه لم تجب بعد كيف تتمايز المسؤولية. بلا هذه الجملة لن نوقّع لأن الجو جيد."],
  ["仍看不到「誰的承諾」。在這句出現前，中方不移動。", "“Whose pledge” is still not visible. Until that sentence appears, China does not move.", "On ne voit toujours pas « l'engagement de qui ». Avant que cette phrase apparaisse, la Chine ne bouge pas.", "Todavía no se ve «el compromiso de quién». Hasta que aparezca esa frase, China no se mueve.", "«Чьё обязательство» всё ещё не видно. Пока эта фраза не появится, Китай не двигается.", "ما زال «تعهد من» غير ظاهر. قبل أن تظهر هذه الجملة، لا تتحرك الصين."],
  ["原則我們已經說過。請把它寫成「補充不能替代」，而不是再複述一次。", "We have already stated the principle. Please write it as “a supplement cannot replace”, not as one more retelling.", "Nous avons déjà dit le principe. Écris-le comme « un complément ne peut pas remplacer », au lieu de le redire.", "Ya dijimos el principio. Escríbelo como «un complemento no puede sustituir», en vez de volver a contarlo.", "Принцип мы уже сказали. Запишите его как «дополнение не может заменить», а не перескажите ещё раз.", "قلنا المبدأ. اكتبه «التكملة لا تستطيع أن تحل محل»، لا تعد سرده."],
  ["原話不必再念。寫進草案的時候，補充兩個字要在。", "The original words do not need to be read again. When it is written into the draft, the word supplement has to be there.", "Les mots d'origine n'ont pas à être relus. Quand cela s'écrit dans le projet, le mot complément doit être là.", "Las palabras originales no hace falta volver a leerlas. Cuando se escriba en el proyecto, la palabra complemento tiene que estar.", "Исходные слова не нужно читать снова. Когда это вписывается в проект, слово «дополнение» должно быть там.", "لا حاجة لإعادة قراءة الكلام الأصلي. حين يُكتب في المشروع، يجب أن تكون كلمة التكملة موجودة."],
  ["請用公約原則或公共資金的資料來說，不要只重複肯尼亞的利益。", "Please speak with the Convention's principle or with material on public finance. Do not only repeat Kenya's interests.", "Parle avec le principe de la Convention ou avec une donnée sur le financement public. Ne répète pas seulement les intérêts du Kenya.", "Habla con el principio de la Convención o con un dato sobre financiamiento público. No repitas solo los intereses de Kenia.", "Говорите принципом Конвенции или материалом о государственном финансировании. Не повторяйте только интересы Кении.", "تكلم بمبدأ الاتفاقية أو بمادة عن التمويل العام. لا تكرر مصالح كينيا فقط."],
  ["肯尼亞的社區需求，不能代替責任如何區別。", "Kenya's community needs cannot stand in for how responsibility is differentiated.", "Les besoins communautaires du Kenya ne peuvent pas remplacer la façon dont la responsabilité se différencie.", "Las necesidades comunitarias de Kenia no pueden sustituir cómo se diferencia la responsabilidad.", "Потребности общин Кении не могут заменить то, как различается ответственность.", "احتياجات مجتمعات كينيا لا تستطيع أن تحل محل كيفية تمايز المسؤولية."],
  ["原則還在原位", "The principle is still in place", "Le principe est encore à sa place", "El principio sigue en su sitio", "Принцип всё ещё на месте", "المبدأ ما زال في مكانه"],
  ["補充可以談", "A supplement can be discussed", "Un complément peut se discuter", "Un complemento se puede discutir", "Дополнение можно обсуждать", "يمكن مناقشة التكملة"],
  ["先看責任怎麼寫", "First see how responsibility is written", "Voir d'abord comment la responsabilité est écrite", "Ver primero cómo se escribe la responsabilidad", "Сначала смотреть, как записана ответственность", "انظر أولًا كيف تُكتب المسؤولية"],
  ["原則被換掉了", "The principle was replaced", "Le principe a été remplacé", "El principio fue sustituido", "Принцип заменили", "استُبدل المبدأ"],
  ["留下一個自願的公私窗口，並擋住任何新的強制分攤公式。", "Keep a voluntary public-private window, and block any new compulsory assessment formula.", "Garder une fenêtre volontaire public-privé, et bloquer toute nouvelle formule de répartition obligatoire.", "Mantener una ventana voluntaria público-privada y bloquear cualquier fórmula nueva de reparto obligatorio.", "Оставить добровольное государственно-частное окно и не пустить любую новую формулу обязательных долей.", "الإبقاء على نافذة طوعية بين العام والخاص، ومنع أي صيغة جديدة للتقاسم الإلزامي."],
  ["我們可以談窗口的大小。新的分攤公式，這席不開。", "We can talk about the size of the window. A new assessment formula: this seat does not open that.", "Nous pouvons parler de la taille de la fenêtre. Une nouvelle formule de répartition : ce siège ne l'ouvre pas.", "Podemos hablar del tamaño de la ventana. Una fórmula nueva de reparto: este asiento no la abre.", "О размере окна говорить можно. Новую формулу долей это место не открывает.", "يمكننا الحديث عن حجم النافذة. صيغة تقاسم جديدة: هذا المقعد لا يفتحها."],
  ["我們不會接受新的強制分攤公式。自願、可衡量、透明，這三個詞要同時在，美國才繼續聽。", "We will not accept a new compulsory assessment formula. Voluntary, measurable, and transparent must all be there before the United States keeps listening.", "Nous n'accepterons pas une nouvelle formule de répartition obligatoire. Volontaire, mesurable et transparent doivent être là ensemble pour que les États-Unis continuent d'écouter.", "No aceptaremos una fórmula nueva de reparto obligatorio. Voluntario, medible y transparente tienen que estar juntos para que Estados Unidos siga escuchando.", "Новую формулу обязательных долей мы не примем. Добровольно, измеримо и прозрачно должны быть вместе, чтобы США продолжали слушать.", "لن نقبل صيغة جديدة للتقاسم الإلزامي. يجب أن توجد معًا طوعي وقابل للقياس وشفاف حتى تواصل الولايات المتحدة الاستماع."],
  ["公式這條沒有彈性。你若想聽新的內容，聽這個：自願窗口可以小，但不能被寫成自動攤派。", "The formula line has no flexibility. If you want to hear something new, hear this: the voluntary window can be small, but it cannot be written as an automatic assessment.", "La ligne de la formule n'a pas de souplesse. Si tu veux entendre quelque chose de nouveau, entends ceci : la fenêtre volontaire peut être petite, mais elle ne peut pas être écrite comme une répartition automatique.", "La línea de la fórmula no tiene flexibilidad. Si quieres oír algo nuevo, oye esto: la ventana voluntaria puede ser pequeña, pero no puede escribirse como un reparto automático.", "У строки о формуле нет гибкости. Если хотите услышать новое, услышьте это: добровольное окно может быть маленьким, но его нельзя записать как автоматическую долю.", "سطر الصيغة بلا مرونة. إذا أردت سماع شيء جديد، فاسمع هذا: يمكن أن تكون النافذة الطوعية صغيرة، لكن لا يمكن كتابتها تقاسمًا تلقائيًا."],
  ["保留自願性的公私窗口，並寫明項目降低了什麼風險，我們可以不反對。公共贈款可以是一個窗口，不要把它寫成向任何國家自動攤派。", "Keep a voluntary public-private window, and write what risk the project lowers, and we can refrain from opposing. Public grants can be one window. Do not write them as an automatic assessment on any country.", "Garde une fenêtre volontaire public-privé, et écris quel risque le projet réduit : nous pouvons ne pas nous opposer. Les dons publics peuvent être une fenêtre. Ne les écris pas comme une répartition automatique sur un pays.", "Mantén una ventana voluntaria público-privada y escribe qué riesgo reduce el proyecto: podemos no oponernos. Las subvenciones públicas pueden ser una ventana. No las escribas como un reparto automático sobre ningún país.", "Сохраните добровольное государственно-частное окно и запишите, какой риск снижает проект, — мы можем не возражать. Государственные гранты могут быть одним окном. Не записывайте их как автоматическую долю для любой страны.", "أبقِ نافذة طوعية بين العام والخاص، واكتب أي خطر يخفضه المشروع، ويمكن ألا نعترض. يمكن أن تكون المنح العامة نافذة. لا تكتبها تقاسمًا تلقائيًا على أي بلد."],
  ["我們要看的是風險怎麼被量出來。分攤公式不用再問，答案不會變。", "What we want to see is how the risk is measured. Do not ask the assessment formula again. The answer will not change.", "Ce que nous voulons voir, c'est comment le risque est mesuré. Ne redemande pas la formule de répartition. La réponse ne changera pas.", "Lo que queremos ver es cómo se mide el riesgo. No vuelvas a preguntar la fórmula de reparto. La respuesta no cambiará.", "Мы хотим видеть, как измеряется риск. Формулу долей больше не спрашивайте. Ответ не изменится.", "ما نريد رؤيته هو كيف يُقاس الخطر. لا تعد سؤال صيغة التقاسم. الجواب لن يتغير."],
  ["贈款加報告，透明度是好的。若整個文件只剩贈款、沒有自願窗口，美國傾向棄權，而不是連署。", "Grants plus a report: transparency is good. If the whole paper is only grants, with no voluntary window, the United States leans toward abstaining, not cosponsoring.", "Dons plus rapport : la transparence est bonne. Si tout le document ne reste que des dons, sans fenêtre volontaire, les États-Unis penchent pour l'abstention, pas le coparrainage.", "Subvenciones más informe: la transparencia es buena. Si todo el documento queda solo en subvenciones, sin ventana voluntaria, Estados Unidos se inclina a abstenerse, no a copatrocinar.", "Гранты плюс отчёт: прозрачность хороша. Если весь документ — только гранты, без добровольного окна, США склоняются к воздержанию, а не к соавторству.", "منح مع تقرير: الشفافية جيدة. إذا بقي المستند منحًا فقط بلا نافذة طوعية، تميل الولايات المتحدة إلى الامتناع لا إلى المشاركة في التقديم."],
  ["報告我們歡迎。缺的是自願窗口那一欄。只有贈款的文本，我們不會簽名。", "We welcome the report. What is missing is the column for a voluntary window. A text that is only grants: we will not sign.", "Nous accueillons le rapport. Ce qui manque, c'est la colonne de la fenêtre volontaire. Un texte qui n'est que des dons, nous ne le signerons pas.", "El informe es bienvenido. Lo que falta es la columna de la ventana voluntaria. Un texto que es solo subvenciones no lo firmaremos.", "Отчёт мы приветствуем. Не хватает графы добровольного окна. Текст из одних грантов мы не подпишем.", "نرحب بالتقرير. الناقص هو عمود النافذة الطوعية. النص الذي هو منح فقط لن نوقّعه."],
  ["把私人資本寫成主體，符合我們的優先。前線國家會把這句讀成贈款被拿掉。靠近美國，不代表這份草案對肯尼亞安全。", "Writing private capital as the main body matches our priority. Front-line countries will read that sentence as grants being removed. Coming closer to the United States does not mean this draft is safe for Kenya.", "Écrire le capital privé comme corps principal correspond à notre priorité. Les pays de première ligne liront cette phrase comme un retrait des dons. Se rapprocher des États-Unis ne veut pas dire que ce projet est sûr pour le Kenya.", "Escribir el capital privado como cuerpo principal coincide con nuestra prioridad. Los países de primera línea leerán esa frase como que se quitaron las subvenciones. Acercarse a Estados Unidos no significa que este proyecto sea seguro para Kenia.", "Записать частный капитал основным телом совпадает с нашим приоритетом. Страны переднего края прочтут эту фразу как удаление грантов. Приближение к США не значит, что проект безопасен для Кении.", "كتابة رأس المال الخاص جسمًا تطابق أولويتنا. ستقرأ بلدان الخط الأمامي هذه الجملة على أن المنح أُزيلت. الاقتراب من الولايات المتحدة لا يعني أن هذا المشروع آمن لكينيا."],
  ["這個方向你已經知道我們喜歡。也請你自己算清楚：贈款若退成陪襯，你的席位會付出什麼。", "You already know we like this direction. Please also count it yourself: if grants step back into decoration, what does your seat pay?", "Tu sais déjà que nous aimons cette direction. Calcule aussi toi-même : si les dons reculent en décor, que paie ton siège ?", "Ya sabes que nos gusta esta dirección. Calcula también tú: si las subvenciones retroceden a adorno, ¿qué paga tu asiento?", "Вы уже знаете, что нам нравится это направление. Посчитайте и сами: если гранты отойдут в украшение, чем заплатит ваше место?", "تعرف أننا نحب هذا الاتجاه. احسب أنت أيضًا: إذا تراجعت المنح إلى زينة، فماذا يدفع مقعدك؟"],
  ["社區通道可以討論。請加上可衡量的結果。單是開門，還不足以讓我們簽名。", "A community channel can be discussed. Please add a result that can be measured. Opening the door alone is not enough for us to sign.", "Un canal communautaire peut se discuter. Ajoute un résultat mesurable. Ouvrir la porte seule ne suffit pas pour que nous signions.", "Un canal comunitario se puede discutir. Añade un resultado que se pueda medir. Abrir la puerta sola no basta para que firmemos.", "Канал общин можно обсуждать. Добавьте измеримый результат. Одной открытой двери нам недостаточно, чтобы подписать.", "يمكن مناقشة قناة للمجتمع. أضف نتيجة يمكن قياسها. فتح الباب وحده لا يكفي لتوقيعنا."],
  ["開門可以留。我們還要一句：風險降低了多少，由誰核對。", "The open door can stay. We still need one sentence: how much the risk fell, and who checks it.", "La porte ouverte peut rester. Il nous faut encore une phrase : de combien le risque a baissé, et qui le vérifie.", "La puerta abierta puede quedarse. Aún necesitamos una frase: cuánto bajó el riesgo y quién lo comprueba.", "Открытая дверь может остаться. Нам всё ещё нужна фраза: насколько снизился риск и кто это сверяет.", "يمكن أن يبقى الباب مفتوحًا. نحتاج جملة أخرى: كم انخفض الخطر، ومن يتحقق منه."],
  ["這則碰到自願、私人工具或問責。美國可以把它當成不反對的理由。強制分攤仍然免談。", "This touches voluntary tools, private tools, or accountability. The United States can treat it as a reason not to oppose. A compulsory assessment is still off the table.", "Ceci touche le volontaire, les outils privés ou la redevabilité. Les États-Unis peuvent le prendre comme raison de ne pas s'opposer. La répartition obligatoire reste hors discussion.", "Esto toca lo voluntario, las herramientas privadas o la rendición de cuentas. Estados Unidos puede tomarlo como razón para no oponerse. El reparto obligatorio sigue fuera de discusión.", "Это касается добровольного, частных инструментов или подотчётности. США могут принять это как причину не возражать. Обязательная доля по-прежнему не обсуждается.", "هذا يمس الطوعي أو الأدوات الخاصة أو المساءلة. يمكن للولايات المتحدة أن تعدّه سببًا لعدم الاعتراض. التقاسم الإلزامي ما زال خارج النقاش."],
  ["工具這點對上了。請把它放在自願窗口，不要寫成新的義務。", "The tool point fits. Please put it in the voluntary window. Do not write it as a new duty.", "Le point sur l'outil correspond. Mets-le dans la fenêtre volontaire. Ne l'écris pas comme une obligation nouvelle.", "El punto de la herramienta encaja. Ponlo en la ventana voluntaria. No lo escribas como un deber nuevo.", "Пункт об инструменте подходит. Поставьте его в добровольное окно. Не записывайте новой обязанностью.", "نقطة الأداة تطابق. ضعها في النافذة الطوعية. لا تكتبها واجبًا جديدًا."],
  ["這則沒有說明私人資本或自願窗口放在哪裡。我們先不調整。", "This one does not say where private capital or the voluntary window sits. We do not adjust yet.", "Celle-ci ne dit pas où se trouvent le capital privé ou la fenêtre volontaire. Nous n'ajustons pas encore.", "Esta no dice dónde están el capital privado o la ventana voluntaria. Todavía no ajustamos.", "Эта не говорит, где частный капитал или добровольное окно. Мы пока не сдвигаемся.", "هذه لا تبيّن أين يوضع رأس المال الخاص أو النافذة الطوعية. لا نعدّل بعد."],
  ["仍看不到可衡量的那個窗口。美國這席先停在原地。", "The window that can be measured is still not visible. The United States seat stays where it is.", "La fenêtre mesurable n'est toujours pas visible. Le siège des États-Unis reste où il est.", "La ventana que se puede medir todavía no se ve. El asiento de Estados Unidos se queda donde está.", "Окна, которое можно измерить, всё ещё не видно. Место США остаётся на месте.", "النافذة التي يمكن قياسها ما زالت غير ظاهرة. مقعد الولايات المتحدة يبقى حيث هو."],
  ["你引用了我們的話。接下來要看草案是否保留自願性。", "You cited our words. Next we look at whether the draft keeps the voluntary character.", "Tu as cité nos mots. Ensuite, nous regardons si le projet garde le caractère volontaire.", "Citaste nuestras palabras. Después miramos si el proyecto mantiene el carácter voluntario.", "Вы процитировали наши слова. Дальше смотрим, сохраняет ли проект добровольный характер.", "استشهدت بكلامنا. بعد ذلك نرى إن كان المشروع يبقي الطابع الطوعي."],
  ["原話收到。自願性要出現在條款裡，不是只出現在你的複述。", "The original words are received. The voluntary character has to appear in a clause, not only in your retelling.", "Mots d'origine reçus. Le caractère volontaire doit apparaître dans une clause, pas seulement dans ta reprise.", "Palabras originales recibidas. El carácter voluntario tiene que aparecer en una cláusula, no solo en tu relato.", "Исходные слова получены. Добровольный характер должен появиться в пункте, а не только в вашем пересказе.", "وصل الكلام الأصلي. يجب أن يظهر الطابع الطوعي في بند، لا في إعادتك فقط."],
  ["肯尼亞的主張本身不是美國的決策依據。請指向自願性、私人工具，或可核對的成果。", "Kenya's claim by itself is not the basis of a United States decision. Please point to the voluntary character, a private tool, or a result that can be checked.", "La position du Kenya n'est pas, à elle seule, la base d'une décision des États-Unis. Pointe le caractère volontaire, un outil privé, ou un résultat vérifiable.", "La propuesta de Kenia por sí sola no es la base de una decisión de Estados Unidos. Señala el carácter voluntario, una herramienta privada o un resultado que se pueda comprobar.", "Позиция Кении сама по себе не основание решения США. Укажите добровольный характер, частный инструмент или результат, который можно сверить.", "مطلب كينيا وحده ليس أساس قرار الولايات المتحدة. أشر إلى الطابع الطوعي أو أداة خاصة أو نتيجة يمكن التحقق منها."],
  ["再講肯尼亞的利益，不會變成美國的窗口。請換一則對得上自願或可衡量的資料。", "Saying Kenya's interests again will not become the United States window. Please change to material that fits voluntary or measurable.", "Redire les intérêts du Kenya ne deviendra pas la fenêtre des États-Unis. Change pour une donnée qui correspond au volontaire ou au mesurable.", "Volver a decir los intereses de Kenia no se volverá la ventana de Estados Unidos. Cambia a un dato que encaje con lo voluntario o lo medible.", "Ещё раз сказать интересы Кении не станет окном США. Смените на материал, который подходит к добровольному или измеримому.", "تكرار مصالح كينيا لن يصبح نافذة الولايات المتحدة. غيّر إلى مادة تطابق الطوعي أو القابل للقياس."],
  ["自願窗口留著", "The voluntary window is still there", "La fenêtre volontaire est encore là", "La ventana voluntaria sigue ahí", "Добровольное окно ещё здесь", "النافذة الطوعية ما زالت موجودة"],
  ["還在量風險", "Still measuring the risk", "Mesure encore le risque", "Todavía mide el riesgo", "Всё ещё измеряет риск", "ما زال يقيس الخطر"],
  ["先不要談分攤", "Do not talk about assessment yet", "Ne parle pas encore de répartition", "No hables todavía de reparto", "Пока не говорите о долях", "لا تتحدث عن التقاسم بعد"],
  ["看到強制就退", "Steps back at anything compulsory", "Recule dès que c'est obligatoire", "Retrocede al ver lo obligatorio", "Отступает, увидев обязательность", "يتراجع حين يرى الإلزام"],
];
